'use server';

import {
  generateInitialEstimate,
} from '@/ai/flows/generate-initial-estimate-from-prompt';
import { z } from 'zod';
import type { InitialEstimateInput, InitialEstimateOutput } from '@/ai/schemas/initial-estimate';
import { getNextStep } from '@/ai/flows/get-next-step-flow';
import type { NextStepInput, NextStepOutput } from '@/ai/schemas/next-step';
import { pingAI } from '@/ai/flows/ping-flow';
import { InitialEstimateInputSchema } from '@/ai/schemas/initial-estimate';

const formSchema = InitialEstimateInputSchema;


export async function createEstimate(
  input: InitialEstimateInput
): Promise<InitialEstimateOutput> {
  console.log('[Action] createEstimate: Received input', JSON.stringify(input, null, 2));
  try {
    const validatedInput = formSchema.parse(input);
    const output = await generateInitialEstimate(validatedInput);
    return output;
  } catch (error: any) {
    console.error('Error generating initial estimate:', error);
    if (error instanceof z.ZodError) {
      throw new Error(`Invalid form input: ${error.errors.map(e => `${e.path.join('.')} - ${e.message}`).join(', ')}`);
    }
    // Re-throw the original error if it's not a Zod error
    throw error;
  }
}


export async function getConversationalResponse(
  history: NextStepInput['history'],
  collectedData: NextStepInput['collectedData']
): Promise<NextStepOutput> {
  console.log('--- CONVERSATIONAL TURN START ---');
  console.log('History:', JSON.stringify(history, null, 2));
  console.log('Collected Data (before):', JSON.stringify(collectedData, null, 2));

  try {
    const output = await getNextStep({ history, collectedData });
    console.log('Flow Output:', JSON.stringify(output, null, 2));
    console.log('--- CONVERSATIONAL TURN END ---');
    return output;
  } catch (error: any) {
     console.error('FATAL: Error in getConversationalResponse:', error);
     if (error.stack) {
       console.error(error.stack);
     }
     console.log('--- CONVERSATIONAL TURN END (WITH ERROR) ---');
     // Provide a fallback response in case the flow itself throws an error
    return {
        response: `I'm sorry, I've encountered an unexpected error: ${error.message || 'Unknown error'}. Please try again or use the form.`,
        updatedData: collectedData,
        isComplete: false,
    };
  }
}

export async function testAIConnection(): Promise<string> {
  try {
    const result = await pingAI();
    return result;
  } catch (error: any) {
    console.error('Error testing AI connection:', error);
    return `Failed to test AI connection: ${error.message}`;
  }
}
