'use client';

import { useState, useEffect, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '@/components/ui/card';
import {
  Loader2,
  Sparkles,
  AlertCircle,
  MessageSquare,
  FileText,
  User,
  Wand2,
  Wifi,
  Download,
  Save,
} from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { createEstimate, getConversationalResponse, testAIConnection } from './actions';
import type { InitialEstimateOutput, InitialEstimateInput } from '@/ai/schemas/initial-estimate';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Textarea } from '@/components/ui/textarea';
import { cn } from '@/lib/utils';
import { InitialEstimateInputSchema } from '@/ai/schemas/initial-estimate';
import { useUser, useFirestore } from '@/firebase';
import { setDocumentNonBlocking } from '@/firebase/non-blocking-updates';
import { collection, doc } from 'firebase/firestore';

const formSchema = InitialEstimateInputSchema;

type Message = { role: 'model' | 'user'; content: string };

function ChatInterface({
  messages,
  onSubmit,
  isLoading,
}: {
  messages: Message[];
  onSubmit: (content: string) => void;
  isLoading: boolean;
}) {
  const [input, setInput] = useState('');
  const scrollAreaRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollAreaRef.current) {
      scrollAreaRef.current.scrollTo({
        top: scrollAreaRef.current.scrollHeight,
        behavior: 'smooth',
      });
    }
  }, [messages]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim()) {
      onSubmit(input);
      setInput('');
    }
  };
  return (
    <Card>
      <CardHeader>
        <CardTitle>Conversational Estimate</CardTitle>
        <CardDescription>
          Answer a few questions to generate your budget estimate.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <div className="h-[400px] flex flex-col">
          <ScrollArea className="flex-1 pr-4" ref={scrollAreaRef}>
            <div className="space-y-6">
              {messages.map((message, index) => (
                <div
                  key={index}
                  className={cn(
                    'flex items-start gap-3',
                    message.role === 'user' && 'justify-end'
                  )}
                >
                  {message.role === 'model' && (
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        <Wand2 className="h-4 w-4" />
                      </AvatarFallback>
                    </Avatar>
                  )}
                  <div
                    className={cn(
                      'rounded-lg p-3 max-w-[80%]',
                      message.role === 'model'
                        ? 'bg-muted'
                        : 'bg-primary text-primary-foreground'
                    )}
                  >
                    <p className="text-sm">{message.content}</p>
                  </div>
                  {message.role === 'user' && (
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        N
                      </AvatarFallback>
                    </Avatar>
                  )}
                </div>
              ))}
               {isLoading && messages.length > 0 && messages[messages.length-1].role === 'user' && (
                 <div className="flex items-start gap-3">
                    <Avatar className="h-8 w-8">
                      <AvatarFallback>
                        <Wand2 className="h-4 w-4" />
                      </AvatarFallback>
                    </Avatar>
                    <div className="rounded-lg p-3 bg-muted">
                        <Loader2 className="h-5 w-5 animate-spin" />
                    </div>
                 </div>
               )}
            </div>
          </ScrollArea>
          <form onSubmit={handleFormSubmit} className="mt-4 flex gap-2">
            <Textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Type your message..."
              className="flex-1"
              rows={1}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleFormSubmit(e);
                }
              }}
              disabled={isLoading}
            />
            <Button type="submit" disabled={isLoading || !input.trim()}>
              Send
            </Button>
          </form>
        </div>
      </CardContent>
    </Card>
  );
}

function FormInput({ form, onSubmit, isLoading }: { form: any; onSubmit: any; isLoading: boolean }) {
    return (
        <Card>
            <CardHeader>
              <CardTitle>Project Details</CardTitle>
              <CardDescription>
                Enter your commercial renovation project details to generate a budget estimate.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Form {...form}>
                <form
                  onSubmit={form.handleSubmit(onSubmit)}
                  className="space-y-6"
                >
                  <FormField
                    control={form.control}
                    name="projectName"
                    render={({ field }) => (
                      <FormItem>
                        <FormLabel>Project Name</FormLabel>
                        <FormControl>
                          <Input placeholder="e.g., Downtown Office Remodel" {...field} value={field.value ?? ''} />
                        </FormControl>
                        <FormMessage />
                      </FormItem>
                    )}
                  />
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="squareFootage"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Project Square Footage</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 5000" {...field} value={field.value ?? ''} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="ceilingHeight"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Ceiling Height (ft)</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 12" {...field} value={field.value ?? ''} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                   <FormField
                      control={form.control}
                      name="ceilingType"
                      render={({ field }) => (
                      <FormItem>
                          <FormLabel>Ceiling Type</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                          <FormControl>
                              <SelectTrigger>
                              <SelectValue placeholder="Select a ceiling type" />
                              </SelectTrigger>
                          </FormControl>
                          <SelectContent>
                              <SelectItem value="Standard">Standard (Drywall/Tiles)</SelectItem>
                              <SelectItem value="Open">Open (Exposed Ductwork)</SelectItem>
                          </SelectContent>
                          </Select>
                          <FormDescription>
                          HVAC costs are higher for open ceilings.
                          </FormDescription>
                          <FormMessage />
                      </FormItem>
                      )}
                  />
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <FormField
                      control={form.control}
                      name="planType"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Plan Type</FormLabel>
                          <Select onValueChange={field.onChange} defaultValue={field.value}>
                            <FormControl>
                              <SelectTrigger>
                                <SelectValue placeholder="Select a plan type" />
                              </SelectTrigger>
                            </FormControl>
                            <SelectContent>
                              <SelectItem value="Open Plan">Open Plan</SelectItem>
                              <SelectItem value="Mixed Use">Mixed Use</SelectItem>
                            </SelectContent>
                          </Select>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={form.control}
                      name="privateOffices"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Private Offices</FormLabel>
                          <FormControl>
                            <Input type="number" placeholder="e.g., 3" {...field} value={field.value ?? ''} />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                  </div>
                  <Button type="submit" disabled={isLoading} className="w-full">
                    {isLoading ? (
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    ) : (
                      <Sparkles className="mr-2 h-4 w-4" />
                    )}
                    Generate Estimate
                  </Button>
                </form>
              </Form>
            </CardContent>
          </Card>
    )
}

function CollectedInfoCard({ data }: { data: Partial<InitialEstimateInput> }) {
  const fields = [
    { key: 'projectName', label: 'Project Name' },
    { key: 'squareFootage', label: 'Square Footage' },
    { key: 'planType', label: 'Plan Type' },
    { key: 'privateOffices', label: 'Private Offices' },
    { key: 'ceilingType', label: 'Ceiling Type' },
    { key: 'ceilingHeight', label: 'Ceiling Height' },
  ];

  return (
    <Card>
      <CardHeader>
        <CardTitle>Collected Information</CardTitle>
        <CardDescription>
          Here's what I've gathered from our conversation so far.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        {fields.map(field => {
          const value = data[field.key as keyof typeof data];
          return (
            <div key={field.key} className="flex justify-between items-center text-sm">
              <span className="text-muted-foreground">{field.label}:</span>
              {value ? (
                <span className="font-medium">{String(value)}</span>
              ) : (
                <span className="italic text-muted-foreground/70">Not provided</span>
              )}
            </div>
          );
        })}
      </CardContent>
    </Card>
  );
}

export default function EstimatePage() {
  const [view, setView] = useState<'chat' | 'form'>('chat');
  const [isLoading, setIsLoading] = useState(false);
  const [estimate, setEstimate] = useState<InitialEstimateOutput | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [collectedData, setCollectedData] = useState<Partial<InitialEstimateInput>>({});
  const { toast } = useToast();
  const { user } = useUser();
  const firestore = useFirestore();

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      projectName: '',
      squareFootage: undefined,
      ceilingHeight: undefined,
      privateOffices: undefined,
      planType: 'Open Plan',
      ceilingType: 'Standard',
    },
  });

  const handleTestConnection = async () => {
    toast({
      title: 'AI Connection Test',
      description: 'Pinging AI assistant...',
    });
    const result = await testAIConnection();
    toast({
      title: 'AI Connection Test Result',
      description: result,
    });
  };

  const startEstimateGeneration = async (data: InitialEstimateInput) => {
    try {
      // Validate the final data before generating the estimate.
      const fullData = InitialEstimateInputSchema.parse(data);
      const finalResult = await createEstimate(fullData);
      setEstimate(finalResult);
    } catch (error: any) {
      console.error("Estimate generation failed", error);
      toast({
        variant: 'destructive',
        title: 'Error Generating Estimate',
        description: error.message || 'The final data was invalid. Please check the collected information.',
      });
    }
  }

  const handleConversationalSubmit = async (content: string) => {
    setIsLoading(true);
    setEstimate(null); // Clear previous estimate

    const newHistory: Message[] = [...messages, { role: 'user', content }];
    setMessages(newHistory);

    try {
      const result = await getConversationalResponse(newHistory, collectedData);

      // Add AI response to chat
      setMessages((prev) => [...prev, { role: 'model', content: result.response }]);
      
      // Update our local state with the data the AI extracted
      setCollectedData(result.updatedData);

      // If the AI says the conversation is complete, generate the estimate
      if (result.isComplete) {
        // We need to ensure all data is valid before creating the estimate
        await startEstimateGeneration(result.updatedData as InitialEstimateInput);
      }
    } catch (error: any) {
      console.error("Conversational submit error", error);
      toast({
        variant: 'destructive',
        title: 'An error occurred',
        description: 'The AI assistant is having trouble. Please try again or switch to the form.',
      });
      // Restore messages to pre-error state to allow user to retry
      setMessages(messages);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDownloadPdf = (estimateData: InitialEstimateOutput) => {
    const doc = new jsPDF();
    const projectName = collectedData.projectName || 'Untitled Project';
  
    // Add header
    doc.setFontSize(22);
    doc.text("RenoAI Budget Estimate", 14, 20);
    doc.setFontSize(12);
    doc.text(`Project: ${projectName}`, 14, 28);
    doc.text(`Date: ${new Date().toLocaleDateString()}`, 14, 34);
  
    // Add Total Budget
    doc.setFontSize(16);
    doc.text("Estimated Total Budget", 14, 50);
    doc.setFontSize(28);
    doc.setTextColor(34, 139, 34); // A green color
    doc.text(estimateData.estimatedBudget, 14, 60);
    doc.setTextColor(0, 0, 0); // Reset text color
  
    // Add Itemized Costs table
    autoTable(doc, {
      startY: 70,
      head: [['Work Item', 'Estimated Cost']],
      body: [
        ['Drywall', estimateData.drywallCost],
        ['Electrical', estimateData.electricalCost],
        ['HVAC', estimateData.hvacCost],
      ],
      theme: 'grid',
      headStyles: { fillColor: [41, 128, 185] }, // A blue color for the header
    });
  
    const finalY = (doc as any).lastAutoTable.finalY || 100;
  
    // Add Assumptions
    doc.setFontSize(14);
    doc.text("Assumptions", 14, finalY + 15);
    doc.setFontSize(10);
    const assumptionsText = doc.splitTextToSize(estimateData.assumptions, 180);
    doc.text(assumptionsText, 14, finalY + 22);

    const assumptionsHeight = doc.getTextDimensions(assumptionsText).h;
  
    // Add Disclaimer
    doc.setFontSize(14);
    doc.text("Disclaimer", 14, finalY + 22 + assumptionsHeight + 10);
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    const disclaimerText = doc.splitTextToSize(estimateData.disclaimer, 180);
    doc.text(disclaimerText, 14, finalY + 22 + assumptionsHeight + 17);
  
    // Save the PDF
    doc.save(`${projectName}-Estimate.pdf`);
  };

  const handleSaveEstimate = () => {
    if (!user) {
      toast({
        variant: 'destructive',
        title: 'Authentication Error',
        description: 'You must be logged in to save an estimate.',
      });
      return;
    }
    if (!estimate || !collectedData.projectName) {
      toast({
        variant: 'destructive',
        title: 'Missing Data',
        description: 'Cannot save incomplete estimate data.',
      });
      return;
    }

    const projectEstimateRef = doc(collection(firestore, 'users', user.uid, 'projectEstimates'));
    const projectEstimateId = projectEstimateRef.id;

    const projectEstimateData = {
      id: projectEstimateId,
      projectName: collectedData.projectName,
      totalBudget: Number(estimate.estimatedBudget.replace(/[^0-9.-]+/g, "")),
      createdDate: new Date().toISOString(),
      userId: user.uid,
      notes: `Ceiling Height: ${collectedData.ceilingHeight}ft, Ceiling Type: ${collectedData.ceilingType}, Plan Type: ${collectedData.planType}, Private Offices: ${collectedData.privateOffices}, Square Footage: ${collectedData.squareFootage}sq ft.`,
    };

    setDocumentNonBlocking(projectEstimateRef, projectEstimateData, { merge: false });

    const lineItems = [
      { description: 'Drywall', totalCost: Number(estimate.drywallCost.replace(/[^0-9.-]+/g,"")), category: 'Materials & Labor' },
      { description: 'Electrical', totalCost: Number(estimate.electricalCost.replace(/[^0-9.-]+/g,"")), category: 'Materials & Labor' },
      { description: 'HVAC', totalCost: Number(estimate.hvacCost.replace(/[^0-9.-]+/g,"")), category: 'Materials & Labor' },
    ];

    const lineItemsCollectionRef = collection(firestore, 'users', user.uid, 'projectEstimates', projectEstimateId, 'estimateLineItems');

    lineItems.forEach(item => {
        const lineItemRef = doc(lineItemsCollectionRef);
        const lineItemData = {
          id: lineItemRef.id,
          projectEstimateId: projectEstimateId,
          description: item.description,
          quantity: 1,
          unitCost: item.totalCost,
          totalCost: item.totalCost,
          category: item.category,
        };
        setDocumentNonBlocking(lineItemRef, { ...lineItemData, id: lineItemRef.id }, { merge: false });
    });

    toast({
      title: 'Estimate Saved!',
      description: `Project "${collectedData.projectName}" has been saved successfully.`,
    });
  };

  useEffect(() => {
    if (view === 'chat' && messages.length === 0) {
      setMessages([
        {
          role: 'model',
          content:
            "Welcome to RenoAI! To start your budget estimate, what would you like to name this project?",
        },
      ]);
    }
  }, [view, messages.length]);

  async function onFormSubmit(values: z.infer<typeof formSchema>) {
    setIsLoading(true);
    setEstimate(null);
    setCollectedData(values);
    try {
      const parsedValues = formSchema.parse(values);
      const result = await createEstimate(parsedValues);
      setEstimate(result);
    } catch (error: any) {
      toast({
        variant: 'destructive',
        title: 'An error occurred',
        description: error.message || 'Failed to generate the estimate. Please try again later.',
      });
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="flex-1 space-y-4 p-4 md:p-8 pt-6">
      <div className="flex items-center justify-between space-y-2">
        <h1 className="text-3xl font-bold tracking-tight font-headline">New Estimate</h1>
        <div className="flex items-center gap-2">
           <Button variant="outline" size="sm" onClick={handleTestConnection}>
              <Wifi className="mr-2 h-4 w-4" />
              Test AI
            </Button>
           <Button variant={view === 'chat' ? 'default' : 'outline'} size="sm" onClick={() => setView('chat')}>
              <MessageSquare className="mr-2 h-4 w-4" />
              Chat
            </Button>
            <Button variant={view === 'form' ? 'default' : 'outline'} size="sm" onClick={() => setView('form')}>
              <FileText className="mr-2 h-4 w-4" />
              Form
            </Button>
        </div>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div>
          {view === 'chat' ? (
            <ChatInterface messages={messages} onSubmit={handleConversationalSubmit} isLoading={isLoading} />
          ) : (
            <FormInput form={form} onSubmit={onFormSubmit} isLoading={isLoading} />
          )}
        </div>
        <div>
          <div className="space-y-8">
            {isLoading && !estimate && (
              <Card>
                <CardHeader>
                  <CardTitle>Generating Your Estimate...</CardTitle>
                  <CardDescription>
                    Our AI is analyzing your project. Please wait a moment.
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="space-y-2 animate-pulse">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-2/3"></div>
                  </div>
                   <div className="space-y-2 animate-pulse delay-150">
                     <div className="h-8 bg-muted rounded w-1/3"></div>
                     <div className="h-4 bg-muted rounded w-full"></div>
                     <div className="h-4 bg-muted rounded w-4/5"></div>
                  </div>
                </CardContent>
              </Card>
            )}
            {estimate ? (
              <>
                <Card className="bg-green-50 dark:bg-green-900/20 border-accent">
                  <CardHeader>
                    <div className="flex w-full items-start justify-between">
                      <div>
                        <CardTitle>Estimated Budget</CardTitle>
                        <CardContent className="p-0 pt-2">
                          <p className="text-5xl font-bold text-green-700 dark:text-green-400">
                            {estimate.estimatedBudget}
                          </p>
                        </CardContent>
                      </div>
                      <div className='flex gap-2'>
                        <Button variant="outline" size="sm" onClick={() => handleDownloadPdf(estimate)}>
                          <Download className="mr-2 h-4 w-4" />
                          PDF
                        </Button>
                         <Button variant="default" size="sm" onClick={handleSaveEstimate}>
                          <Save className="mr-2 h-4 w-4" />
                          Save
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                </Card>
                 <Card>
                  <CardHeader>
                    <CardTitle>Cost Breakdown</CardTitle>
                    <CardDescription>
                      Here is a breakdown of the major cost categories.
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <ul className="space-y-3">
                      <li className="flex justify-between items-center text-sm">
                        <span className="text-muted-foreground">Drywall</span>
                        <span className="font-medium">{estimate.drywallCost}</span>
                      </li>
                      <li className="flex justify-between items-center text-sm">
                        <span className="text-muted-foreground">Electrical</span>
                        <span className="font-medium">{estimate.electricalCost}</span>
                      </li>
                      <li className="flex justify-between items-center text-sm">
                        <span className="text-muted-foreground">HVAC</span>
                        <span className="font-medium">{estimate.hvacCost}</span>
                      </li>
                    </ul>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader>
                    <CardTitle>Assumptions</CardTitle>
                    <CardDescription>
                      The estimate is based on the following assumptions:
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <p className="text-muted-foreground whitespace-pre-wrap">{estimate.assumptions}</p>
                  </CardContent>
                </Card>
                <Card>
                  <CardHeader className="flex flex-row items-center gap-2">
                    <AlertCircle className="h-5 w-5 text-amber-500" />
                    <CardTitle>Disclaimer</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm text-muted-foreground">
                      {estimate.disclaimer}
                    </p>
                  </CardContent>
                </Card>
              </>
            ) : !isLoading && (
              <>
                {view === 'chat' ? (
                  <CollectedInfoCard data={collectedData} />
                ) : (
                  <Card className="flex flex-col items-center justify-center text-center p-8 min-h-[400px]">
                      <CardHeader>
                        <Sparkles className="h-16 w-16 mx-auto text-muted-foreground/50" />
                        <CardTitle className="mt-4">Your AI-Powered Estimate</CardTitle>
                      </CardHeader>
                      <CardContent>
                        <p className="text-muted-foreground">
                          Your generated budget report will appear here once you enter your project details.
                        </p>
                      </CardContent>
                    </Card>
                )}
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
